// symMerge 使用 Pok-Son Kim 和 Arne Kutzner 的 SymMerge 算法合并
// 两个排序的子序列 data[a:m] 和 data[m:b]，"Stable Minimum Storage Merging by Symmetric Comparisons"，
// 在 Susanne Albers 和 Tomasz Radzik 编辑的《Algorithms - ESA 2004》中，
// 计算机科学讲义卷 3221，第 714-723 页。Springer，2004。
//
// 设 M = m-a 和 N = b-n。不失一般性，M < N。
// 递归深度受 ceil(log(N+M)) 限制。
// 该算法需要 O(M*log(N/M + 1)) 次对 data.Less 的调用。
// 该算法需要 O((M+N)*log(M)) 次对 data.Swap 的调用。
//
// 论文给出 O((M+N)*log(M)) 作为赋值数量，假设一个旋转算法
// 使用 O(M+N+gcd(M+N)) 次赋值。论文中的论证对 Swap 操作同样适用，
// 特别是因为块交换旋转仅使用 O(M+N) 次 Swap。
//
// symMerge 假设非退化参数：a < m && m < b。
// 让调用者检查此条件可以消除许多叶子递归调用，这提高了性能。
func symMerge(data Interface, a, m, b int) {
	// 通过直接将 data[a] 插入到 data[m:b]
	// 来避免 symMerge 的不必要递归，如果 data[a:m] 只包含一个元素。
	if m-a == 1 {
		// 使用二进制搜索找到最小索引 i，
		// 使得对于 m <= i < b，data[i] >= data[a]。
		// 如果不存在这样的索引，则以 i == b 退出搜索循环。
		i := m
		j := b
		for i < j {
			h := int(uint(i+j) >> 1)
			if data.Less(h, a) {
				i = h + 1
			} else {
				j = h
			}
		}
		// 交换值直到 data[a] 到达 i 之前的位置。
		for k := a; k < i-1; k++ {
			data.Swap(k, k+1)
		}
		return
	}

	// 通过直接将 data[m] 插入到 data[a:m]
	// 来避免 symMerge 的不必要递归，如果 data[m:b] 只包含一个元素。
	if b-m == 1 {
		// 使用二进制搜索找到最小索引 i，
		// 使得对于 a <= i < m，data[i] > data[m]。
		// 如果不存在这样的索引，则以 i == m 退出搜索循环。
		i := a
		j := m
		for i < j {
			h := int(uint(i+j) >> 1)
			if !data.Less(m, h) {
				i = h + 1
			} else {
				j = h
			}
		}
		// 交换值直到 data[m] 到达位置 i。
		for k := m; k > i; k-- {
			data.Swap(k, k-1)
		}
		return
	}

	mid := int(uint(a+b) >> 1)
	n := mid + m
	var start, r int
	if m > mid {
		start = n - b
		r = mid
	} else {
		start = a
		r = m
	}
	p := n - 1

	for start < r {
		c := int(uint(start+r) >> 1)
		if !data.Less(p-c, c) {
			start = c + 1
		} else {
			r = c
		}
	}

	end := n - start
	if start < m && m < end {
		rotate(data, start, m, end)
	}
	if a < start && start < mid {
		symMerge(data, a, start, mid)
	}
	if mid < end && end < b {
		symMerge(data, mid, end, b)
	}
}

// rotate 在数据中旋转两个连续块 u = data[a:m] 和 v = data[m:b]：
// 形式为 'x u v y' 的数据变为 'x v u y'。
// rotate 最多执行 b-a 次对 data.Swap 的调用，
// 并假设非退化参数：a < m && m < b。
func rotate(data Interface, a, m, b int) {
	i := m - a
	j := b - m

	for i != j {
		if i > j {
			swapRange(data, m-i, m, j)
			i -= j
		} else {
			swapRange(data, m-i, m+j-i, i)
			j -= i
		}
	}
	// i == j
	swapRange(data, m-i, m, i)
}
